import logging
from taf.ul.mobile.ui.android.mobile import Mobile
from taf.ul.mobile.ui.android.exceptions import SelectFailure


class SamsungMobile(Mobile):

    _SETTING_MOBILE_NETWORKS_ACTIVITY = "com.samsung.android.app.telephonyui/.netsettings.ui.NetSettingsActivity"

    _SETTING_APP = "com.samsung.android.app.telephonyui"

    def switch_network_mode(self, mode_name, *args):
        if self._get_configured_network_mode_name() == mode_name:
            logging.info("has selected specified mode, no action")
            return

        self._select_5g_network_mode(mode_name)

        if self._get_configured_network_mode_name() != mode_name:
            raise SelectFailure(mode_name)

    def get_network_mode(self):
        return self._get_configured_network_mode_name()

    def _select_5g_network_mode(self, mode_name):
        self._switch_to_network_mode_setting_page()
        self._click_menu(mode_name)

    def _get_configured_network_mode_name(self):
        self._switch_to_network_mode_setting_page()
        return self._get_selected_checkedtextview_node_title()

    def _switch_to_network_mode_setting_page(self):
        self._switch_to_mobile_networks_setting()
        self._tap_network_mode()

    def _open_mobile_networks(self):
        self._click_menu("Connections")

    def _tap_mobile_networks(self):
        self._click_menu("Mobile networks")

    def _tap_network_mode(self):
        self._click_menu("Network mode")

    def switch_apn(self, apn_name):
        if self.get_access_point_name() == apn_name:
            logging.info("has selected specified apn, no action")
        else:
            self._select_apn(apn_name)
            selected_node_title = self.get_access_point_name()
            if selected_node_title != apn_name:
                raise SelectFailure(selected_node_title)

    def get_access_point_name(self):
        self._switch_to_access_point_names_page()
        return self._get_selected_node_title()

    def _switch_to_access_point_names_page(self):
        self._switch_to_mobile_networks_setting()
        self._tap_access_point_names()

    def _select_apn(self, apn_name):
        self._click_radio_button_by_title(apn_name)

    def _tap_access_point_names(self):
        self._click_menu("Access Point Names")

    def enable_volte_calls(self):
        if self._is_volte_calls_switch_enable():
            return

        self._tap_volte_calls_switch()

        if not self._is_volte_calls_switch_enable():
            raise SelectFailure

    def disable_volte_calls(self):
        if not self._is_volte_calls_switch_enable():
            return

        self._tap_volte_calls_switch()

        if self._is_volte_calls_switch_enable():
            raise SelectFailure

    def _is_volte_calls_switch_enable(self):
        self._switch_to_volte_calls_page()
        nodes = self._get_widgetswitch_nodes()
        return self._get_widgetswitch_node_text(nodes[-1]).lower() == "on"

    def _tap_volte_calls_switch(self):
        self._switch_to_volte_calls_page()
        nodes = self._get_widgetswitch_nodes()
        self._tap_widgetswitch_node(nodes[-1])

    def _switch_to_volte_calls_page(self):
        self._switch_to_mobile_networks_setting()

    def _switch_to_mobile_networks_setting(self):
        self._adb_proxy.force_stop_setting()
        self._adb_proxy.stop_app_activity(self._SETTING_APP)
        output = self._adb_proxy.start_app_activity(self._SETTING_MOBILE_NETWORKS_ACTIVITY)
        if output and "Error" in output:
            raise SelectFailure("start activity {} failed".format(self._SETTING_MOBILE_NETWORKS_ACTIVITY))
